20	Mmu::Mmu(const SimContext& ctx,
21	        const char* name,
22	        uint32_t num_ports)
23	  : SimObject<Mmu>(ctx, name)
24	  , ReqIn (num_ports, this)
25	  , RspOut(num_ports, this)
26	  , ReqOut(num_ports, this)
27	  , RspIn (num_ports, this)
28	  , num_ports_(num_ports)
29	  , tlb_(VX_CFG_TLB_SIZE)
30	{}
31	
32	Mmu::~Mmu() = default;
33	
34	void Mmu::on_reset() {
35	  ptw_state_ = PTW_IDLE;
36	  // SATP is set externally via set_satp(); don't clear on simulator reset.
37	}
38	
39	void Mmu::set_satp(uint64_t satp) {
40	  satp_ = std::make_unique<SATP_t>(satp);
41	  tlb_.flush();  // sfence.vma
42	}
43	
44	bool Mmu::needs_translation(uint64_t addr) const {
45	  (void)addr;
46	  // The runtime installs identity PTEs at boot for every PA-addressed
47	  // region (IO MMIO, kernel image, page table, stacks), so any access
48	  // post-SATP-set walks the page table — there is no longer a need to
49	  // address-range bypass. The only path that skips translation is one
50	  // issued before SATP is programmed (BARE mode); this covers the
51	  // few instruction fetches between reset and the kernel's csrw satp.
52	  if (!satp_ || satp_->get_mode() == BARE) return false;
53	  return true;
54	}
55	
56	void Mmu::start_ptw(uint64_t va, ACCESS_TYPE type, MemReq orig, uint32_t port) {
57	  // Walk from the root table down: level VX_VM_PT_LEVEL-1 .. 0
58	  // (Sv32: L1->L0; Sv39: L2->L1->L0). The root table is at the SATP PPN.
59	  ptw_state_     = PTW_REQ;
60	  ptw_level_     = VX_VM_PT_LEVEL - 1;
61	  ptw_cur_ppn_   = satp_->get_base_ppn();
62	  ptw_vaddr_     = va;
63	  ptw_type_      = type;
64	  ptw_orig_req_  = orig;
65	  ptw_orig_port_ = port;
66	  walk_start_cyc_= SimPlatform::instance().cycles();
67	  ++walks_;
68	}
69	
70	void Mmu::on_ptw_response(const MemRsp& rsp) {
71	  // Extract the PTE from the cache-line payload at the recorded PTE
72	  // address (low bits give the byte offset within the line). A PTE is
73	  // VX_VM_PTE_SIZE bytes — 4 for Sv32, 8 for Sv39.
74	  uint64_t pte_bytes = 0;
75	  if (rsp.data) {
76	    uint32_t byte_off = (uint32_t)(ptw_pte_addr_ & (VX_CFG_MEM_BLOCK_SIZE - 1));
77	    std::memcpy(&pte_bytes,
78	                reinterpret_cast<const uint8_t*>(rsp.data->data()) + byte_off,
79	                VX_VM_PTE_SIZE);
80	  }
81	  PTE_t pte(pte_bytes);
82	
83	  // Validity check per RISC-V privileged spec (Sv32/Sv39).
84	  bool invalid = (pte.v == 0) | ((pte.r == 0) & (pte.w == 1));
85	  if (invalid) {
86	    // Page fault — for now, abort the simulator with a clear message.
87	    // TODO: route a page-fault exception back to the LSU.
88	    std::cerr << "MMU: page fault on PTE at 0x" << std::hex << ptw_pte_addr_
89	              << " (vaddr 0x" << ptw_vaddr_ << ")" << std::dec << std::endl;
90	    std::abort();
91	  }
92	
93	  // A PTE with any of R/W/X set is a leaf; R=W=X=0 is a pointer to the
94	  // next-level table. A leaf found at level L is a (super)page — L0 =
95	  // 4 KB, L1 = megapage, L2 = gigapage; PTW_FILL composes the PA from
96	  // ptw_leaf_level_, so the level just needs to be recorded here.
97	  bool is_leaf = (pte.r != 0) | (pte.w != 0) | (pte.x != 0);
98	  if (is_leaf) {
99	    ptw_final_ppn_  = pte.ppn;
100	    ptw_flags_      = pte.flags;
101	    ptw_leaf_level_ = ptw_level_;
102	    ptw_state_      = PTW_FILL;
103	    return;
104	  }
105	  // Interior node — descend to the next level. A non-leaf at level 0
106	  // means the walk ran out of levels with no leaf: a page fault.
107	  if (ptw_level_ == 0) {
108	    std::cerr << "MMU: page fault — no leaf PTE for vaddr 0x"
109	              << std::hex << ptw_vaddr_ << std::dec << std::endl;
110	    std::abort();
111	  }
112	  ptw_cur_ppn_ = pte.ppn;
113	  --ptw_level_;
114	  ptw_state_   = PTW_REQ;
115	}
116	
117	void Mmu::drive_ptw() {
118	  // Bits of VA per page-table level. Derived from PT geometry:
119	  // VX_VM_PT_SIZE / VX_VM_PTE_SIZE = entries per table = 2^VPN_BITS_PER_LEVEL.
120	  const uint32_t VPN_BITS = log2ceil(VX_VM_PT_SIZE / VX_VM_PTE_SIZE);
121	  const uint64_t VPN_MASK = (1ULL << VPN_BITS) - 1;
122	  switch (ptw_state_) {
123	  case PTW_REQ: {
124	    // Index the page table at the current level by this level's VPN
125	    // slice. The root level uses the SATP base PPN (set in start_ptw);
126	    // deeper levels use the interior PTE's PPN recorded by the response.
127	    uint32_t shift = VX_VM_PAGE_LOG2_SIZE + ptw_level_ * VPN_BITS;
128	    uint64_t vpn   = (ptw_vaddr_ >> shift) & VPN_MASK;
129	    ptw_pte_addr_  = pte_addr(ptw_cur_ppn_, vpn);
130	    MemReq req(MemOp::LD, ptw_pte_addr_, /*data*/nullptr, /*byteen*/0,
131	               PTW_TAG_MARKER, /*hart_id*/0, /*uuid*/0);
132	    if (ReqOut.at(0).try_send(req)) {
133	      DT(4, this->name() << " ptw L" << (uint32_t)ptw_level_
134	                         << "-req: addr=0x" << std::hex << ptw_pte_addr_ << std::dec);
135	      ptw_state_ = PTW_WAIT;
136	    }
137	    break;
138	  }
139	  case PTW_FILL: {
140	    // Compose the PA. For a leaf at level L the low 12 + L*VPN_BITS VA
141	    // bits are the offset within the (super)page — L0 = 4 KB (pgoff
142	    // only), L1 = megapage, L2 = gigapage — and come from the VA, not
143	    // the leaf PPN.
144	    uint32_t off_bits = VX_VM_PAGE_LOG2_SIZE +
145	                        ptw_leaf_level_ * log2ceil(VX_VM_PT_SIZE / VX_VM_PTE_SIZE);
146	    uint64_t off_mask = (1ULL << off_bits) - 1;
147	    uint64_t pa_base = (ptw_final_ppn_ << VX_VM_PAGE_LOG2_SIZE) & ~off_mask;
148	    uint64_t pa = pa_base | (ptw_vaddr_ & off_mask);
149	    // Cache the per-4KB sub-page mapping in the TLB. A megapage walk
150	    // therefore only services the specific 4 KB that triggered the
151	    // miss; subsequent VAs in the same megapage will re-walk (correct,
152	    // just less optimal — fine for the rare system regions we identity-map).
153	    uint64_t vpn = ptw_vaddr_ >> VX_VM_PAGE_LOG2_SIZE;
154	    uint64_t ppn_4kb = pa >> VX_VM_PAGE_LOG2_SIZE;
155	    tlb_.fill(vpn, ppn_4kb, ptw_flags_);
156	    MemReq translated = ptw_orig_req_;
157	    translated.addr = pa;
158	    if (ReqOut.at(ptw_orig_port_).try_send(translated)) {
159	      walk_latency_ += (SimPlatform::instance().cycles() - walk_start_cyc_);
160	      ptw_state_ = PTW_IDLE;
161	    }
162	    break;
163	  }
164	  default:
165	    break;
166	  }
167	}
168	
169	void Mmu::on_tick() {
170	  // 1) Drain responses. PTW responses are claimed by the FSM; everything
171	  // else flows back upstream unchanged.
172	  for (uint32_t p = 0; p < num_ports_; ++p) {
173	    if (RspIn.at(p).empty()) continue;
174	    const MemRsp& rsp = RspIn.at(p).peek();
175	    if (rsp.tag & PTW_TAG_MARKER) {
176	      // PTW response. Only PTW state cares about it.
177	      if (ptw_state_ == PTW_WAIT) {
178	        on_ptw_response(rsp);
179	      }
180	      RspIn.at(p).pop();
181	    } else {
182	      if (RspOut.at(p).full()) continue;
183	      RspOut.at(p).send(rsp, 1);
184	      RspIn.at(p).pop();
185	    }
186	  }
187	
188	  // 2) Run PTW FSM — emit pending PTE fetches / fill.
189	  if (ptw_state_ != PTW_IDLE && ptw_state_ != PTW_WAIT) {
190	    drive_ptw();
191	  }
192	
193	  // 3) Forward incoming requests. Bypass for non-translated addresses;
194	  // TLB-hit translates inline; TLB-miss kicks PTW (if free).
195	  for (uint32_t p = 0; p < num_ports_; ++p) {
196	    if (ReqIn.at(p).empty()) continue;
197	    const MemReq& req = ReqIn.at(p).peek();
198	
199	    if (!needs_translation(req.addr)) {
200	      if (ReqOut.at(p).try_send(req)) {
201	        ReqIn.at(p).pop();
202	      }
203	      continue;
204	    }
205	
206	    uint64_t vpn = req.addr >> VX_VM_PAGE_LOG2_SIZE;
207	    auto [hit, ppn] = tlb_.lookup(vpn);
208	    if (hit) {
209	      MemReq translated = req;
210	      translated.addr = (ppn << VX_VM_PAGE_LOG2_SIZE) |
211	                        (req.addr & ((1ULL << VX_VM_PAGE_LOG2_SIZE) - 1));
212	      if (ReqOut.at(p).try_send(translated)) {
213	        ReqIn.at(p).pop();
214	      }
215	    } else {
216	      // TLB miss — kick PTW if it's idle. Otherwise this request waits
217	      // (stays at the head of ReqIn[p]) until the in-flight walk completes.
218	      if (ptw_state_ == PTW_IDLE) {
219	        // ACCESS_TYPE inferred from req op (no FETCH on dcache port).
220	        ACCESS_TYPE type = req.is_write() ? ACCESS_TYPE::STORE : ACCESS_TYPE::LOAD;
221	        start_ptw(req.addr, type, req, p);
222	        ReqIn.at(p).pop();
223	      }
224	    }
225	  }
226	}
227	
228	} // namespace vortex
229	
230	#endif // VX_CFG_VM_ENABLE
