15	namespace vortex {
16	
17	Tlb::Tlb(uint32_t size)
18	    : entries_(size)
19	{}
20	
21	std::pair<bool, uint64_t> Tlb::lookup(uint64_t vpn) {
22	  ++reads_;
23	  for (auto& e : entries_) {
24	    if (e.valid && e.vpn == vpn) {
25	      e.mru = true;
26	      ++hits_;
27	      return {true, e.ppn};
28	    }
29	  }
30	  ++misses_;
31	  return {false, 0};
32	}
33	
34	void Tlb::fill(uint64_t vpn, uint64_t ppn, uint8_t flags) {
35	  // Prefer an invalid slot; fall back to a non-MRU victim. If all slots
36	  // are valid AND every slot has mru=true, clear all MRU bits and evict slot 0.
37	  int victim = -1;
38	  for (size_t i = 0; i < entries_.size(); ++i) {
39	    if (!entries_[i].valid) { victim = (int)i; break; }
40	  }
41	  if (victim < 0) {
42	    for (size_t i = 0; i < entries_.size(); ++i) {
43	      if (!entries_[i].mru) { victim = (int)i; break; }
44	    }
45	  }
46	  if (victim < 0) {
47	    // All entries are valid + MRU. Clear MRU bits and pick slot 0.
48	    for (auto& e : entries_) e.mru = false;
49	    victim = 0;
50	  }
51	
52	  if (entries_[victim].valid)
53	    ++evictions_;
54	
55	  entries_[victim].valid = true;
56	  entries_[victim].mru   = true;
57	  entries_[victim].vpn   = vpn;
58	  entries_[victim].ppn   = ppn;
59	  entries_[victim].flags = flags;
60	}
61	
62	void Tlb::flush() {
63	  for (auto& e : entries_) {
64	    e.valid = false;
65	    e.mru = false;
66	  }
67	}
68	
69	} // namespace vortex
70	
71	#endif // VX_CFG_VM_ENABLE
