27	#define BARE 0x0
28	#define SV32 0x1
29	#define SV39 0x8
30	
31	enum ACCESS_TYPE {
32	  LOAD,
33	  STORE,
34	  FETCH
35	};
36	
37	class SATP_t {
38	private:
39	  uint64_t address;
40	  uint16_t asid;
41	  uint8_t  mode;
42	  uint64_t ppn;
43	  uint64_t satp;
44	
45	  static uint64_t bits(uint64_t input, uint8_t s_idx, uint8_t e_idx) {
46	    return (input >> s_idx) & (((uint64_t)1 << (e_idx - s_idx + 1)) - 1);
47	  }
48	  static bool bit(uint64_t input, uint8_t idx) {
49	    return (input) & ((uint64_t)1 << idx);
50	  }
51	
52	public:
53	  SATP_t(uint64_t satp_val) : satp(satp_val) {
54	#if VX_VM_ADDR_MODE == SV32
55	    mode = bit(satp, 31);
56	    asid = bits(satp, 22, 30);
57	    ppn  = bits(satp, 0, 21);
58	#else
59	    mode = bits(satp, 60, 63);
60	    asid = bits(satp, 44, 59);
61	    ppn  = bits(satp, 0, 43);
62	#endif
63	    address = ppn << VX_VM_PAGE_LOG2_SIZE;
64	  }
65	
66	  SATP_t(uint64_t address, uint16_t asid) : address(address), asid(asid) {
67	#if VX_VM_ADDR_MODE == SV32
68	    assert((address >> 32) == 0 && "Upper 32 bits are not zero!");
69	#endif
70	    mode = VX_VM_ADDR_MODE;
71	    ppn = address >> VX_VM_PAGE_LOG2_SIZE;
72	#pragma GCC diagnostic push
73	#pragma GCC diagnostic ignored "-Wshift-count-overflow"
74	#if VX_VM_ADDR_MODE == SV32
75	    satp = (((uint64_t)mode << 31) | ((uint64_t)asid << 22) | ppn);
76	#else
77	    satp = (((uint64_t)mode << 60) | ((uint64_t)asid << 44) | ppn);
78	#endif
79	#pragma GCC diagnostic pop
80	  }
81	
82	  uint8_t  get_mode()     const { return mode; }
83	  uint16_t get_asid()     const { return asid; }
84	  uint64_t get_base_ppn() const { return ppn; }
85	  uint64_t get_satp()     const { return satp; }
86	};
87	
88	class Page_Fault_Exception : public std::runtime_error {
89	public:
90	  Page_Fault_Exception(const std::string& what = "") : std::runtime_error(what) {}
91	  uint64_t addr;
92	  ACCESS_TYPE type;
93	};
94	
95	class PTE_t {
96	private:
97	  uint64_t address;
98	  static uint64_t bits(uint64_t input, uint8_t s_idx, uint8_t e_idx) {
99	    return (input >> s_idx) & (((uint64_t)1 << (e_idx - s_idx + 1)) - 1);
100	  }
101	  static bool bit(uint64_t input, uint8_t idx) {
102	    return (input) & ((uint64_t)1 << idx);
103	  }
104	
105	public:
106	#if VX_VM_ADDR_MODE == SV39
107	  bool N;
108	  uint8_t PBMT;
109	#endif
110	  uint64_t ppn;
111	  uint32_t rsw;
112	  uint32_t flags;
113	  uint8_t level;
114	  bool d, a, g, u, x, w, r, v;
115	  uint64_t pte_bytes;
116	
117	  void set_flags(uint32_t flag) {
118	    this->flags = flag;
119	    d = bit(flags, 7);
120	    a = bit(flags, 6);
121	    g = bit(flags, 5);
122	    u = bit(flags, 4);
123	    x = bit(flags, 3);
124	    w = bit(flags, 2);
125	    r = bit(flags, 1);
126	    v = bit(flags, 0);
127	  }
128	
129	  PTE_t(uint64_t address, uint32_t flags) : address(address) {
130	#if VX_VM_ADDR_MODE == SV39
131	    N = 0;
132	    PBMT = 0;
133	    level = 3;
134	    ppn = address >> VX_VM_PAGE_LOG2_SIZE;
135	    set_flags(flags);
136	    pte_bytes = (ppn << 10) | flags;
137	#else // SV32
138	    assert((address >> 32) == 0 && "Upper 32 bits are not zero!");
139	    level = 2;
140	    ppn = address >> VX_VM_PAGE_LOG2_SIZE;
141	    set_flags(flags);
142	    pte_bytes = (ppn << 10) | flags;
143	#endif
144	  }
145	
146	  PTE_t(uint64_t pte_bytes) : pte_bytes(pte_bytes) {
147	#if VX_VM_ADDR_MODE == SV39
148	    N = bit(pte_bytes, 63);
149	    PBMT = bits(pte_bytes, 61, 62);
150	    level = 3;
151	    ppn = bits(pte_bytes, 10, 53);
152	    address = ppn << VX_VM_PAGE_LOG2_SIZE;
153	#else // SV32
154	    assert((pte_bytes >> 32) == 0 && "Upper 32 bits are not zero!");
155	    level = 2;
156	    ppn = bits(pte_bytes, 10, 31);
157	    address = ppn << VX_VM_PAGE_LOG2_SIZE;
158	#endif
159	    rsw = bits(pte_bytes, 8, 9);
160	    set_flags((uint32_t)(bits(pte_bytes, 0, 7)));
161	  }
162	};
