165	private:
166	  uint64_t address;
167	  uint64_t bits(uint8_t s_idx, uint8_t e_idx) const {
168	    return (address >> s_idx) & (((uint64_t)1 << (e_idx - s_idx + 1)) - 1);
169	  }
