176	  vAddr_t(uint64_t address) : address(address) {
177	#if VX_VM_ADDR_MODE == SV39
178	    level = 3;
179	    vpn = new uint64_t[level];
180	    vpn[2] = bits(30, 38);
181	    vpn[1] = bits(21, 29);
182	    vpn[0] = bits(12, 20);
183	    pgoff  = bits(0, 11);
184	#else // SV32
185	    assert((address >> 32) == 0 && "Upper 32 bits are not zero!");
186	    level = 2;
187	    vpn = new uint64_t[level];
188	    vpn[1] = bits(22, 31);
189	    vpn[0] = bits(12, 21);
190	    pgoff  = bits(0, 11);
191	#endif
192	  }
