75	int VMManager::init() {
76	  uint64_t pt_addr = 0;
77	  std::cout << "VMManager Initialization..." << std::endl;
78	  page_table_mem_ = new MemoryAllocator(VX_MEM_PAGE_TABLE_BASE_ADDR, VX_VM_PT_SIZE_LIMIT, VX_VM_PAGE_SIZE, CACHE_BLOCK_SIZE);
79	  if (page_table_mem_ == nullptr)
80	    return 1;
81	
82	  uint64_t virtual_mem_size = (GLOBAL_MEM_SIZE - ALLOC_BASE_ADDR);
83	#if VX_VM_ADDR_MODE == SV32
84	  // Keep VAs within the 32-bit address space.
85	  uint64_t max_va_end = 0x100000000ULL;
86	  if (ALLOC_BASE_ADDR + virtual_mem_size > max_va_end) {
87	    virtual_mem_size = max_va_end - ALLOC_BASE_ADDR;
88	  }
89	#endif
90	  virtual_mem_ = new MemoryAllocator(ALLOC_BASE_ADDR, virtual_mem_size, VX_VM_PAGE_SIZE, CACHE_BLOCK_SIZE);
91	  if (virtual_mem_ == nullptr)
92	    return 1;
93	
94	  if (VX_VM_ADDR_MODE == BARE) {
95	    DBGPRINT("[RT:init_VM] VA_MODE = BARE MODE(addr= 0x0)\n");
96	  } else {
97	    CHECK_ERR(alloc_page_table(&pt_addr), { return err; });
98	  }
99	
100	  // Stash a local SATP record so need_trans / page_table_walk see the
101	  // PT base. The simulator's hardware MMU sees SATP via the kernel's
102	  // csrw at boot — VMManager does not push it into the simulator.
103	  satp_ = std::make_unique<SATP_t>(pt_addr, /*asid=*/0);
104	
105	  if (VX_VM_ADDR_MODE != BARE) {
106	    // Identity-map system regions that are PA-addressed by the kernel
107	    // and runtime: IO MMIO range and the high region containing the
108	    // page table + per-warp stacks. The kernel image is mapped later
109	    // via mem_reserve() once the loader knows its extents.
110	    CHECK_ERR(install_identity_map(0, VX_MEM_USER_BASE_ADDR), { return err; });
111	    CHECK_ERR(install_identity_map(VX_MEM_PAGE_TABLE_BASE_ADDR,
112	                                   GLOBAL_MEM_SIZE - VX_MEM_PAGE_TABLE_BASE_ADDR), {
113	      return err;
114	    });
115	  }
116	  // install_identity_map() already flushed; an extra flush here is a
117	  // cheap no-op if nothing else dirtied the shadow.
118	  return flush();
119	}
