121	bool VMManager::need_trans(uint64_t dev_pAddr) {
122	  (void)dev_pAddr;
123	  // System PA regions (IO, kernel image, page table, stack) are
124	  // identity-mapped at boot, so every address goes through PTW
125	  // except those issued before SATP is set or in BARE mode.
126	  if (this->is_satp_unset() || get_mode() == BARE)
127	    return false;
128	  return true;
