131	uint64_t VMManager::map_p2v(uint64_t ppn, uint32_t flags) {
132	  if (addr_mapping.find(ppn) != addr_mapping.end())
133	    return addr_mapping[ppn];
134	
135	  uint64_t vpn;
136	  if (randomize_va_) {
137	    const int MAX_ATTEMPTS = 1000;
138	    bool allocated = false;
139	    for (int attempt = 0; attempt < MAX_ATTEMPTS; ++attempt) {
140	      uint64_t va_range_start = ALLOC_BASE_ADDR;
141	      uint64_t va_range_end = VX_MEM_PAGE_TABLE_BASE_ADDR;
142	#if VX_VM_ADDR_MODE == SV32
143	      uint64_t max_va = 0xFFFFFFFFULL;
144	      if (va_range_end > max_va)
145	        va_range_end = max_va;
146	#endif
147	      uint64_t va_range_size = va_range_end - va_range_start;
148	      uint64_t max_pages = va_range_size >> VX_VM_PAGE_LOG2_SIZE;
149	      std::uniform_int_distribution<uint64_t> dist(0, max_pages - 1);
150	      uint64_t random_page_offset = dist(rng_);
151	      uint64_t candidate_va = va_range_start + (random_page_offset << VX_VM_PAGE_LOG2_SIZE);
152	
153	      bool in_use = false;
154	      for (const auto& mapping : addr_mapping) {
155	        if (mapping.second == (candidate_va >> VX_VM_PAGE_LOG2_SIZE)) {
156	          in_use = true;
157	          break;
158	        }
159	      }
160	      if (!in_use && virtual_mem_->reserve(candidate_va, VX_VM_PAGE_SIZE) == 0) {
161	        vpn = candidate_va >> VX_VM_PAGE_LOG2_SIZE;
162	        allocated = true;
163	        break;
164	      }
165	    }
166	    if (!allocated) {
167	      virtual_mem_->allocate(VX_VM_PAGE_SIZE, &vpn);
168	      vpn >>= VX_VM_PAGE_LOG2_SIZE;
169	    }
170	  } else {
171	    virtual_mem_->allocate(VX_VM_PAGE_SIZE, &vpn);
172	    vpn >>= VX_VM_PAGE_LOG2_SIZE;
173	  }
174	
175	  CHECK_ERR(update_page_table(ppn, vpn, pte_flags_from_access(flags)), );
176	  addr_mapping[ppn] = vpn;
177	  flush();
178	  return vpn;
179	}
