181	int VMManager::phy_to_virt_map(uint64_t size, uint64_t* dev_pAddr, uint32_t flags) {
182	  if (!need_trans(*dev_pAddr))
183	    return 0;
184	
185	  uint64_t init_pAddr = *dev_pAddr;
186	  // Round up: a sub-page allocation still needs one PTE. A plain
187	  // `size >> PAGE_LOG2` truncates to 0 for any buffer < 4 KB, leaving
188	  // it unmapped.
189	  uint64_t num_pages = (size + VX_VM_PAGE_SIZE - 1) >> VX_VM_PAGE_LOG2_SIZE;
190	  uint64_t base_ppn = init_pAddr >> VX_VM_PAGE_LOG2_SIZE;
191	
192	  uint64_t base_vpn;
193	  if (addr_mapping.find(base_ppn) != addr_mapping.end()) {
194	    base_vpn = addr_mapping[base_ppn];
195	  } else {
196	    uint64_t base_va = 0;
197	    if (randomize_va_) {
198	      const int MAX_ATTEMPTS = 1000;
199	      bool allocated = false;
200	      for (int attempt = 0; attempt < MAX_ATTEMPTS && !allocated; ++attempt) {
201	        uint64_t va_range_start = ALLOC_BASE_ADDR;
202	        uint64_t va_range_end = VX_MEM_PAGE_TABLE_BASE_ADDR;
203	#if VX_VM_ADDR_MODE == SV32
204	        uint64_t max_va = 0xFFFFFFFFULL;
205	        if (va_range_end > max_va)
206	          va_range_end = max_va;
207	#endif
208	        uint64_t va_range_size = va_range_end - va_range_start;
209	        uint64_t max_pages = (va_range_size >> VX_VM_PAGE_LOG2_SIZE) - num_pages;
210	        std::uniform_int_distribution<uint64_t> dist(0, max_pages - 1);
211	        uint64_t random_page_offset = dist(rng_);
212	        uint64_t candidate_va = va_range_start + (random_page_offset << VX_VM_PAGE_LOG2_SIZE);
213	
214	        bool range_available = true;
215	        for (uint64_t i = 0; i < num_pages && range_available; ++i) {
216	          uint64_t test_vpn = (candidate_va >> VX_VM_PAGE_LOG2_SIZE) + i;
217	          for (const auto& mapping : addr_mapping) {
218	            if (mapping.second == test_vpn) {
219	              range_available = false;
220	              break;
221	            }
222	          }
223	        }
224	        if (range_available && virtual_mem_->reserve(candidate_va, size) == 0) {
225	          base_va = candidate_va;
226	          allocated = true;
227	        }
228	      }
229	      if (!allocated) {
230	        base_va = 0;
231	        CHECK_ERR(virtual_mem_->allocate(size, &base_va), );
232	      }
233	    } else {
234	      base_va = 0;
235	      CHECK_ERR(virtual_mem_->allocate(size, &base_va), );
236	    }
237	    base_vpn = base_va >> VX_VM_PAGE_LOG2_SIZE;
238	  }
239	
240	  uint64_t init_vAddr = (base_vpn << VX_VM_PAGE_LOG2_SIZE) | (init_pAddr & ((1 << VX_VM_PAGE_LOG2_SIZE) - 1));
241	
242	  for (uint64_t i = 0; i < num_pages; i++) {
243	    uint64_t ppn = base_ppn + i;
244	    uint64_t vpn = base_vpn + i;
245	    if (addr_mapping.find(ppn) == addr_mapping.end()) {
246	      CHECK_ERR(update_page_table(ppn, vpn, pte_flags_from_access(flags)), );
247	      addr_mapping[ppn] = vpn;
248	    }
249	  }
250	
251	  assert(page_table_walk(init_vAddr) == init_pAddr && "VA->PA round-trip mismatch");
252	
253	  *dev_pAddr = init_vAddr;
254	  return flush();
255	}
