257	uint8_t VMManager::alloc_page_table(uint64_t* pt_addr) {
258	  CHECK_ERR(page_table_mem_->allocate(VX_VM_PT_SIZE, pt_addr), { return err; });
259	  // Lazily materialize the shadow page (zero-initialized) and mark
260	  // dirty so flush() pushes the zeros to device memory at least once.
261	  auto& page = touch_pt_page(*pt_addr);
262	  std::memset(page.data(), 0, page.size());
263	  return 0;
264	}
265	
266	int16_t VMManager::update_page_table(uint64_t ppn, uint64_t vpn, uint32_t pte_flag, uint8_t leaf_level) {
267	#if VX_VM_ADDR_MODE == SV39
268	  assert((((ppn >> 44) == 0) && ((vpn >> 27) == 0)) && "Upper bits are not zero!");
269	#else
270	  assert((((ppn >> 20) == 0) && ((vpn >> 20) == 0)) && "Upper 12 bits are not zero!");
271	#endif
272	  assert(leaf_level < VX_VM_PT_LEVEL && "leaf_level out of range");
273	  int i = VX_VM_PT_LEVEL - 1;
274	  vAddr_t vaddr(vpn << VX_VM_PAGE_LOG2_SIZE);
275	  uint64_t pte_addr = 0, pte_bytes = 0;
276	  uint64_t pt_addr = 0;
277	  uint64_t cur_base_ppn = get_base_ppn();
278	
279	  while (i >= 0) {
280	    pte_addr = (cur_base_ppn * VX_VM_PT_SIZE) + (vaddr.vpn[i] * VX_VM_PTE_SIZE);
281	    pte_bytes = read_pte(pte_addr);
282	    PTE_t pte_chk(pte_bytes);
283	    bool valid = (pte_chk.v == 1) && ((pte_bytes & 0xFFFFFFFF) != 0xbaadf00d);
284	    if (valid && (pte_chk.r || pte_chk.w || pte_chk.x)) {
285	      // An existing leaf (super)page already maps this VA — a PTE with any of
286	      // R/W/X set is a leaf, not a pointer to the next level (RISC-V priv
287	      // spec). Descending into it would walk mapped data as a page table.
288	      // Re-mapping is idempotent when the existing leaf already yields the
289	      // requested translation — install_identity_map legitimately re-covers a
290	      // sub-range of a coarser identity superpage installed by
291	      // VMManager::init() — while a different target is a genuine conflict.
292	      uint64_t span = uint64_t(1) << (i * VM_VPN_BITS);   // 4 KB pages per level-i page
293	      uint64_t mapped_ppn = (pte_chk.ppn & ~(span - 1)) | (vpn & (span - 1));
294	      return (mapped_ppn == ppn) ? 0 : -1;
295	    }
296	    if (valid) {
297	      cur_base_ppn = pte_chk.ppn;   // interior node — descend
298	    } else {
299	      if (i == (int)leaf_level) {
300	        // Leaf: caller supplies the raw PTE permission bits.
301	        PTE_t new_pte(ppn << VX_VM_PAGE_LOG2_SIZE, pte_flag);
302	        write_pte(pte_addr, new_pte.pte_bytes);
303	        break;
304	      } else {
305	        // Interior: allocate next-level table; PTE_V only (RWX cleared
306	        // marks it as a pointer to the next-level table per the spec).
307	        alloc_page_table(&pt_addr);
308	        PTE_t new_pte(pt_addr, PTE_V);
309	        write_pte(pte_addr, new_pte.pte_bytes);
310	        cur_base_ppn = new_pte.ppn;
311	      }
312	    }
313	    i--;
314	  }
315	  return 0;
316	}
317	
318	int VMManager::install_identity_map(uint64_t addr, uint64_t size) {
319	  // Per-level page coverage: L0 = VX_VM_PAGE_SIZE, each higher level
320	  // multiplies by PT entries-per-table. SV32: L1=4MB. SV39: L1=2MB, L2=1GB.
321	  constexpr uint64_t PT_FANOUT = VX_VM_PT_SIZE / VX_VM_PTE_SIZE;
322	  uint64_t level_size[VX_VM_PT_LEVEL];
323	  level_size[0] = VX_VM_PAGE_SIZE;
324	  for (uint8_t l = 1; l < VX_VM_PT_LEVEL; ++l) {
325	    level_size[l] = level_size[l - 1] * PT_FANOUT;
326	  }
327	
328	  // Identity-mapped system regions get full R/W/X; the host-side ACL
329	  // (set via mem_access) is the actual permission boundary.
330	  constexpr uint32_t IDENTITY_PTE_FLAGS = PTE_V | PTE_R | PTE_W | PTE_X;
331	
332	  (void)virtual_mem_->reserve(addr, size);
333	
334	  uint64_t cur = addr;
335	  uint64_t end = addr + size;
336	  while (cur < end) {
337	    uint64_t remaining = end - cur;
338	    uint8_t leaf_level = 0;
339	    for (int l = VX_VM_PT_LEVEL - 1; l > 0; --l) {
340	      if ((cur % level_size[l]) == 0 && remaining >= level_size[l]) {
341	        leaf_level = (uint8_t)l;
342	        break;
343	      }
344	    }
345	    uint64_t vpn = cur >> VX_VM_PAGE_LOG2_SIZE;
346	    CHECK_ERR(update_page_table(vpn, vpn, IDENTITY_PTE_FLAGS, leaf_level), {
347	      return err;
348	    });
349	    cur += level_size[leaf_level];
350	  }
351	  return flush();
352	}
353	
354	uint64_t VMManager::page_table_walk(uint64_t vAddr_bits) {
355	  if (!need_trans(vAddr_bits))
356	    return vAddr_bits;
357	
358	  uint8_t level = VX_VM_PT_LEVEL;
359	  int i = level - 1;
360	  vAddr_t vaddr(vAddr_bits);
361	  uint64_t pte_addr = 0, pte_bytes = 0;
362	  uint64_t cur_base_ppn = get_base_ppn();
363	
364	  while (true) {
365	    pte_addr = (cur_base_ppn * VX_VM_PT_SIZE) + (vaddr.vpn[i] * VX_VM_PTE_SIZE);
366	    pte_bytes = read_pte(pte_addr);
367	    PTE_t pte(pte_bytes);
368	    assert(((pte.pte_bytes & 0xFFFFFFFF) != 0xbaadf00d) && "uninitialized PTE");
369	
370	    if ((pte.v == 0) | ((pte.r == 0) & (pte.w == 1))) {
371	      throw Page_Fault_Exception("[RT:PTW] invalid entry");
372	    }
373	    if ((pte.r == 0) & (pte.w == 0) & (pte.x == 0)) {
374	      i--;
375	      if (i < 0)
376	        throw Page_Fault_Exception("[RT:PTW] no leaf node");
377	      cur_base_ppn = pte.ppn;
378	      continue;
379	    }
380	    if (pte.r == 0)
381	      throw Page_Fault_Exception("[RT:PTW] permission");
382	    cur_base_ppn = pte.ppn;   // leaf found at level i
383	    break;
384	  }
385	  // Reconstruct the physical address. For a leaf found at level i > 0 (a
386	  // mega/gigapage) the low VX_VM_PAGE_LOG2_SIZE + i*VM_VPN_BITS address bits
387	  // are the offset *within* the superpage and must come from the VA, not
388	  // from the (superpage-aligned) leaf PPN. For a 4 KB leaf (i == 0) this
389	  // reduces to the ordinary ppn<<12 | page-offset.
390	  const uint64_t off_mask =
391	      (uint64_t(1) << (VX_VM_PAGE_LOG2_SIZE + i * VM_VPN_BITS)) - 1;
392	  return ((cur_base_ppn << VX_VM_PAGE_LOG2_SIZE) & ~off_mask)
393	       | (vAddr_bits & off_mask);
394	}
395	
396	// -- shadow PT helpers --------------------------------------------------
397	
398	std::vector<uint8_t>& VMManager::touch_pt_page(uint64_t addr) {
399	  uint64_t page_pa = addr & ~(uint64_t)(VX_VM_PT_SIZE - 1);
400	  auto& page = shadow_pt_[page_pa];
401	  if (page.empty())
402	    page.resize(VX_VM_PT_SIZE, 0);
403	  dirty_pt_pages_.insert(page_pa);
404	  return page;
405	}
406	
407	const std::vector<uint8_t>* VMManager::peek_pt_page(uint64_t addr) const {
408	  uint64_t page_pa = addr & ~(uint64_t)(VX_VM_PT_SIZE - 1);
409	  auto it = shadow_pt_.find(page_pa);
410	  if (it == shadow_pt_.end())
411	    return nullptr;
412	  return &it->second;
413	}
414	
415	void VMManager::write_pte(uint64_t addr, uint64_t value) {
416	  auto& page = touch_pt_page(addr);
417	  uint64_t off = addr - (addr & ~(uint64_t)(VX_VM_PT_SIZE - 1));
418	  // Little-endian byte serialization, matching the device-side PTW
419	  // which fetches VX_VM_PTE_SIZE bytes from this address.
420	  for (uint64_t i = 0; i < VX_VM_PTE_SIZE; ++i) {
421	    page[off + i] = (value >> (i << 3)) & 0xff;
422	  }
423	}
424	
425	uint64_t VMManager::read_pte(uint64_t addr) {
426	  const auto* page = peek_pt_page(addr);
427	#if VX_VM_ADDR_MODE == SV32
428	  uint64_t mask = 0x00000000FFFFFFFFULL;
429	#else
430	  uint64_t mask = 0xFFFFFFFFFFFFFFFFULL;
431	#endif
432	  if (page == nullptr) {
433	    // Unallocated PT page reads as zero (matches device DRAM init
434	    // pattern from cache_init / fresh allocator state).
435	    return 0;
436	  }
437	  uint64_t off = addr - (addr & ~(uint64_t)(VX_VM_PT_SIZE - 1));
438	  uint64_t v = 0;
439	  for (uint64_t i = 0; i < VX_VM_PTE_SIZE; ++i) {
440	    v |= (uint64_t)(*page)[off + i] << (i << 3);
441	  }
442	  return v & mask;
443	}
444	
445	int VMManager::flush() {
446	  // One bulk device write per dirty PT page, minimizing DMA transactions.
447	  if (dirty_pt_pages_.empty())
448	    return 0;
449	  for (uint64_t page_pa : dirty_pt_pages_) {
450	    const auto& page = shadow_pt_[page_pa];
451	    dev_io_->write(page.data(), page_pa, page.size());
452	  }
453	  dirty_pt_pages_.clear();
454	  return 0;
455	}
