8	#pragma once
9	
10	// VMManager is unconditionally compiled into the generic libvortex.so —
11	// VM is discovered at runtime (CP DEV_CAPS.VM_ENABLED), not via #ifdef.
12	// It is inert (never constructed) on a device without an MMU. No
13	// HW-private VX_config.h dependency: VM config comes from VX_types.h.
14	#include <VX_types.h>
15	
16	#include <cstdint>
17	#include <cstddef>
18	#include <memory>
19	#include <random>
20	#include <unordered_map>
21	#include <unordered_set>
22	#include <vector>
23	#include <mem_alloc.h>
24	#include <vm_types.h>
25	
26	namespace vortex {
27	
28	// Sv32/Sv39 PTE permission bits (RISC-V privileged spec, table 4.4).
29	constexpr uint32_t PTE_V = 1u << 0;
30	constexpr uint32_t PTE_R = 1u << 1;
31	constexpr uint32_t PTE_W = 1u << 2;
32	constexpr uint32_t PTE_X = 1u << 3;
33	constexpr uint32_t PTE_U = 1u << 4;
34	
35	// Driver-supplied raw device-memory I/O. PA-addressed bulk read/write
36	// with no ACL semantics — VMManager batches all PT updates at PT-page
37	// granularity (one transfer per dirty PT page) before reaching this
38	// interface, so the per-call cost amortizes naturally across many
39	// PTEs even on FPGA backends.
40	//
41	// Driver adapters:
42	//   simx, rtlsim : memcpy into the sim's RAM backing store (with the
43	//                  per-RAM ACL temporarily bypassed inside the adapter).
44	//   xrt, opae    : DMA transfer to/from the FPGA's PT region (the same
45	//                  low-level path used by mem_write/mem_read).
46	class DeviceMemIO {
47	public:
48	  virtual ~DeviceMemIO() = default;
49	  virtual void read (void* dst, uint64_t addr, size_t size) = 0;
50	  virtual void write(const void* src, uint64_t addr, size_t size) = 0;
51	};
52	
53	// Host-resident virtual-memory manager. Owns the page-table allocator
54	// (a PA region at VX_MEM_PAGE_TABLE_BASE_ADDR) and a parallel virtual-address
55	// allocator. On every vx_mem_alloc, allocates a PA from the global
56	// pool, then mints a VA + installs PTEs so the kernel can use the VA.
57	//
58	// Page tables are SHADOWED in host memory. All read_pte / write_pte
59	// hit the shadow (host memcpy, no device round-trip). Modifications
60	// mark the touched PT page dirty; the runtime calls flush() (or lets
61	// it run implicitly at the end of each public mutator) to push the
62	// dirty pages to device memory in one bulk transfer per page. This
63	// matches the host-shadow / batched-update pattern used by mainstream
64	// GPU drivers (CUDA, ROCm, Level Zero) and keeps the FPGA DMA path
65	// efficient — a 1 MB allocation costs 1 DMA per ~512 PTEs instead of
66	// 256 individual PTE writes.
67	//
68	// SATP is maintained locally so need_trans / page_table_walk can use
69	// it; the hardware MMU separately receives SATP via the kernel's
70	// csrw at boot (no push from host needed).
